/**
 * The key store: `keys/*.json`, generated by `npm run keys`.
 *
 * `keys/` is gitignored. These are real testnet private keys — never log them,
 * never send them anywhere, never commit them. Only `shared/projects.json`
 * (addresses, which are public) is tracked.
 *
 * Node-only: this module touches the filesystem, so it must never be imported
 * from `web/`. It is deliberately not re-exported from `@upstream/shared`.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { PrivateKey } from '@bsv/sdk'

/** Repo root, resolved from this file so scripts work from any cwd. */
export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..')
export const KEYS_DIR = join(ROOT, 'keys')
export const DATA_DIR = join(ROOT, 'data')

/** Base58 version byte for testnet P2PKH addresses (mainnet is 0x00). */
export const TESTNET_ADDRESS_PREFIX = [0x6f]
/** WIF version byte for testnet private keys (mainnet is 0x80). */
export const TESTNET_WIF_PREFIX = [0xef]

/** One generated key. `privHex` is the secret; `pubKey` and `address` are public. */
export interface KeyRecord {
  /** Label for logs and the UI, e.g. "swarm-agent-007". */
  label: string
  /** 32-byte private key, hex. SECRET. */
  privHex: string
  /** WIF, testnet prefix. SECRET — convenience for importing into a wallet. */
  wif: string
  /** Compressed public key, hex (33 bytes). */
  pubKey: string
  /** Testnet P2PKH address. */
  address: string
}

/** An agent together with the owner whose identity key vouches for it. */
export interface AgentWithOwner {
  agent: KeyRecord
  owner: KeyRecord
}

/** Everything `npm run keys` produces. */
export interface KeyStore {
  projects: KeyRecord[]
  /** Lisa's agent. Her OWNER is her BSV Desktop identity key, signed in the browser. */
  lisa: KeyRecord
  swarm: AgentWithOwner[]
  whale: AgentWithOwner
  /** Sybil agents have no owner at all — that is what the server rejects. */
  sybil: KeyRecord[]
}

/** Generate one fresh key as a testnet record. */
export function generateKey(label: string): KeyRecord {
  const priv = PrivateKey.fromRandom()
  return {
    label,
    privHex: priv.toHex(),
    wif: priv.toWif(TESTNET_WIF_PREFIX),
    pubKey: priv.toPublicKey().toString(),
    address: priv.toAddress(TESTNET_ADDRESS_PREFIX)
  }
}

/** Recover the signing key from a record. */
export const privateKeyOf = (rec: KeyRecord): PrivateKey => PrivateKey.fromHex(rec.privHex)

const fileFor = (name: string): string => join(KEYS_DIR, `${name}.json`)

export function keyFileExists(name: string): boolean {
  return existsSync(fileFor(name))
}

export function writeKeyFile(name: string, value: unknown): string {
  mkdirSync(KEYS_DIR, { recursive: true })
  const path = fileFor(name)
  // mode 0600: owner read/write only. Windows ignores this; harmless there.
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`, { encoding: 'utf8', mode: 0o600 })
  return path
}

export function readKeyFile<T>(name: string): T {
  const path = fileFor(name)
  if (!existsSync(path)) {
    throw new Error(`${path} not found — run \`npm run keys\` first.`)
  }
  return JSON.parse(readFileSync(path, 'utf8')) as T
}

/** Load the whole key store. Throws with a useful message if keys are missing. */
export function loadKeys(): KeyStore {
  return {
    projects: readKeyFile<KeyRecord[]>('projects'),
    lisa: readKeyFile<KeyRecord>('lisa'),
    swarm: readKeyFile<AgentWithOwner[]>('swarm'),
    whale: readKeyFile<AgentWithOwner>('whale'),
    sybil: readKeyFile<KeyRecord[]>('sybil')
  }
}
